import{z as B,x as s,o as n,c as d,q as r,j as A,D as t,d as E,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"分页与碎片管理","description":"","frontmatter":{"title":"分页与碎片管理","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kv-paging-fragmentation.md","filePath":"llm/kv-paging-fragmentation.md","lastUpdated":1791413859000}'),p={name:"llm/kv-paging-fragmentation.md"};function m(D,a,g,c,h,f){const l=s("Mermaid");return n(),d("div",null,[a[2]||(a[2]=r('<h1 id="分页与碎片管理" tabindex="-1">分页与碎片管理 <a class="header-anchor" href="#分页与碎片管理" aria-label="Permalink to &quot;分页与碎片管理&quot;">​</a></h1><div class="epigraph"><p>碎片是承诺与用量之差：按最坏情况预留，就是在为永远不会发生的请求付费。</p><footer>—— 据 Kwon et al., PagedAttention, SOSP 2023 的碎片分析整理</footer></div><p><a href="/llm/kv-lifecycle-ownership">上一课</a>立了所有权状态机：页从池里出来、独占、共享、归还，写权与释放都由引用计数裁决。缺口是页本身怎么切、怎么发：池子管理得不好，所有权再干净，显存也会在「明明还有空」的时候拒绝新请求。本课写碎片的两种形态、分配器的策略，以及利用率该怎么记账。块大小怎么选是<a href="/llm/paged-kv-block-size">已写过的权衡</a>，本课只引用其结论；分页注意力的寻址与 gather 也留在 <a href="/llm/paged-attention">PagedAttention</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>连续预留的账是这样的：按最大长度 \\(n_{\\max}\\) 给每条请求留一整段，实际用到 \\(n\\)。利用率是 \\(n / n_{\\max}\\) 的期望——对话负载里这个比值常不到一半，剩下的是为「万一写长」预付的内部浪费。更糟的是外部碎片：请求来了又走，长短不一，空闲字节总量够接一条新请求，却凑不出一段足够长的连续空间。Kwon 等人在 SOSP 2023 的测量里，现有系统只有约 20%–38% 的 KV 内存真正存了有效数据，其余被预留、内部浪费和外部碎片吃掉。分页的命题就是把这两项同时压掉：空闲页可拼给任何请求，外部碎片基本消失；最后一页没填满的平均浪费从「半段预留」降为「半页」。</p><p><span class="marginnote">直觉类比：连续预留像餐厅只接「包场」——来 2 个人的散客也必须包下 20 桌的大厅，客人坐不满，别人也进不来。分页像改成散座：桌子（页）随便拼给任何一桌，浪费只剩最后一桌没坐满的几个空位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分配器是页池的守门人，要回答三个问题。</p><p><strong>从哪拿</strong>：空闲页用空闲表管理。多数请求每次解码只需一页，first-fit 从表头摘即可；预填充一次要 \\(k=\\lceil n_{\\rm prompt}/B \\rceil\\) 页，可批量摘连续段以减少元数据。预留水位线（watermark）给系统留缓冲：池子低于水位就停止接新请求或触发<a href="/llm/vllm-scheduler">抢占</a>，而不是等到分配失败再回滚。</p><p><strong>何时还</strong>：请求结束、共享引用清零，页回空闲表——这在上课的状态机里。分页特有的问题是<strong>增长中途失败</strong>：解码到一半池子空了，这条请求既不能回滚也不该弃。正确姿势是 admission 时按 \\(n_{\\max}\\) 做准入检查、运行时按需分配，并在水位触发时抢占整条请求换出，而不是让页分配在 decode 中途失败。</p><p><strong>怎么算账</strong>：三种口径必须分开——reserved（池子划给 KV 的总量）、allocated（已挂在块表上的页）、in-use（有效 token 占的槽位）。碎片率 \\(= 1 - {\\rm in\\text{-}use}/{\\rm allocated}\\)，内部碎片全在这里；allocated 与 reserved 之差是没分出去的池。汇报时混用三者，「利用率 90%」可以是三种完全不同的系统。</p><p><span class="marginnote">数字实例：池子 10 GiB，块表已挂 8 GiB，其中有效 token 只占 6 GiB——reserved = 10，allocated = 8，in-use = 6。碎片率 \\(1 - 6/8 = 25\\%\\)，而「利用率」可以是 60%（in-use/reserved）也可以是 75%（in-use/allocated），报哪个都得写明分母。</span></p>',12)),(n(),A(o,null,{default:t(()=>[i(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20ADM%7B%22%E5%87%86%E5%85%A5%EF%BC%9An_max%20%E9%A2%84%E7%AE%97%E5%A4%9F%3F%22%7D%0A%20%20ADM%20--%3E%7C%E5%90%A6%7C%20REJ%5B%22%E6%8B%92%E7%BB%9D%E6%88%96%E6%8E%92%E9%98%9F%22%5D%0A%20%20ADM%20--%3E%7C%E6%98%AF%7C%20PRE%5B%22prefill%EF%BC%9A%E6%89%B9%E9%87%8F%E6%91%98%20k%20%E9%A1%B5%22%5D%0A%20%20PRE%20--%3E%20DEC%5B%22decode%EF%BC%9A%E6%AF%8F%E6%AD%A5%E6%91%98%E4%B8%80%E9%A1%B5%22%5D%0A%20%20DEC%20--%3E%20WM%7B%22%E6%B1%A0%E4%BD%8E%E4%BA%8E%E6%B0%B4%E4%BD%8D%3F%22%7D%0A%20%20WM%20--%3E%7C%E6%98%AF%7C%20PREEMPT%5B%22%E6%8A%A2%E5%8D%A0%2F%E6%8D%A2%E5%87%BA%E6%95%B4%E6%9D%A1%E8%AF%B7%E6%B1%82%22%5D%0A%20%20WM%20--%3E%7C%E5%90%A6%7C%20DEC%0A%20%20DEC%20--%3E%20END%5B%22%E7%BB%93%E6%9D%9F%EF%BC%9A%E5%BC%95%E7%94%A8%E6%B8%85%E9%9B%B6%EF%BC%8C%E9%A1%B5%E5%9B%9E%E7%A9%BA%E9%97%B2%E8%A1%A8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("分页消灭碎片不是魔法，是把「连续性」从物理约束降级为逻辑约定：注意力只认逻辑位置，物理上页散在池里无所谓，代价是内核多做一层译址。于是页大小 \\(B\\) 成了唯一剩余的碎片旋钮：\\(B\\) 大则平均半页浪费是 \\(B/2\\) 个 token 槽，\\(B\\) 小则块表条目多、gather 的合并访问变差。16 与 64 之间选哪个取决于长度分布——短回复为主的负载用大页纯属浪费，这里只引用"),e("a",{href:"/llm/paged-kv-block-size"},"块大小权衡课"),E("的结论：负载相关，别抄默认值。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例：页大小 \\(B=16\\)、平均回复只写 9 个 token 时，每条请求平均浪费 \\(16-9=7\\) 个槽，接近半页；\\(B\\) 降到 4 则浪费最多 3 个槽，但块表条目翻两番，gather 时要跳更多段。页大小就是在「槽内空位」和「表项开销」之间讨价还价。")],-1)),(n(),A(o,null,{default:t(()=>[i(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOG%5B%22%E8%AF%B7%E6%B1%82%E7%9C%BC%E4%B8%AD%E7%9A%84%E5%BA%8F%E5%88%97%3A%20%E9%80%BB%E8%BE%91%E4%BD%8D%E7%BD%AE%200%20%E5%88%B0%20n%22%5D%20--%3E%20T%5B%22%E9%80%BB%E8%BE%91%E8%BF%9E%E7%BB%AD%20%3D%20%E5%8F%AA%E6%98%AF%E5%9D%97%E8%A1%A8%E9%87%8C%E7%9A%84%E9%A1%BA%E5%BA%8F%E7%BA%A6%E5%AE%9A%22%5D%0A%20%20T%20--%3E%20P1%5B%22%E7%89%A9%E7%90%86%E9%A1%B5%203%22%5D%0A%20%20T%20--%3E%20P2%5B%22%E7%89%A9%E7%90%86%E9%A1%B5%2017%22%5D%0A%20%20T%20--%3E%20P3%5B%22%E7%89%A9%E7%90%86%E9%A1%B5%208%22%5D%0A%20%20P1%20--%3E%20K%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E6%A0%B8%E6%8C%89%E5%9D%97%E8%A1%A8%E9%80%90%E9%A1%B5%20gather%22%5D%0A%20%20P2%20--%3E%20K%0A%20%20P3%20--%3E%20K%0A%20%20K%20--%3E%20C%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E5%A4%9A%E4%B8%80%E5%B1%82%E8%AF%91%E5%9D%80%2C%20%E6%94%B6%E7%9B%8A%3A%20%E5%A4%96%E9%83%A8%E7%A2%8E%E7%89%87%E6%B6%88%E5%A4%B1%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>碎片会计决定调度质量。<a href="/llm/serving-metrics">准入控制</a>若按 in-use 估容量，会在碎片高的时刻误判「还有空间」，decode 中途分配失败；若按 reserved 估，又把可用页白白锁死。正确输入是 allocated 加水位。另一处机制是<strong>碎片不会自己长回来</strong>：池子跑久了不会像 C 堆那样在页级产生洞（页等大），但前缀缓存会 pin 住大量只读页，把「空闲表很满、可分配页很少」的状态伪装出来——这要靠缓存逐出回收，不是分配器能解决的。</p><p><span class="marginnote">半页浪费是期望不是上界：长度恰为 \\(B\\) 整数倍的负载内部碎片为零，而长度全部落在 \\(B+1\\) 的负载永远浪费接近整页。评估页大小时用真实长度分布算，别用均匀假设。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>分页不减少有效 token 的字节，<a href="/llm/kv-cache-size-math">那份账</a>由模型宽度和长度决定；它消灭的是预留与碎片，别把容量收益写两遍。CUDA Graph 喜欢静态形状，按「最大页数」锁图的实现会把灵活性换成内部碎片回潮。页池与专家权重、CUDA 上下文共享显存时，水位线要按整卡算。最后，碎片率只在固定负载分布下才可比：短对话测出的 98% 利用率，搬去长文档问答就是另一个系统。</p><p><span class="marginnote">常见误区：把「开了分页」当成容量翻倍的保证。分页只是消灭预留和外部碎片这两块浪费——如果系统本来浪费 60%，收益就大；如果负载长度整齐、本来就装得满，收益接近零。收益大小取决于原来的碎片率。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>连续预留的浪费是预留与用量之差；分页把它压成页内的平均半页。</li><li>分配器三问：从哪拿、何时还、怎么算账；水位线把「中途失败」换成提前抢占。</li><li>reserved / allocated / in-use 三种口径必须分开，碎片率定义在后两者之间。</li><li>页大小是剩余的唯一碎片旋钮，结论随长度分布变。</li><li>前缀缓存 pin 页会伪装成碎片，回收靠逐出不靠分配器。</li><li>出处：Kwon et al., PagedAttention, SOSP 2023（20%–38% 有效利用率与碎片分析）；块大小结论见本仓库 PagedAttention 与分页 KV 课。</li></ul>',7))])}const P=B(p,[["render",m]]);export{u as __pageData,P as default};
